import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Diagnostics and safe evidence","description":"","frontmatter":{"title":"Diagnostics and safe evidence","docId":"developer.diagnostics","translationKey":"developer.diagnostics","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"bd492eda2007394d29d152e20ec0dba70614f06e6d29b75a3b741ed6b23f11b4","translationRevision":"bd492eda2007394d29d152e20ec0dba70614f06e6d29b75a3b741ed6b23f11b4","order":130},"headers":[],"relativePath":"en/developer/diagnostics.md","filePath":"en/developer/diagnostics.md","lastUpdated":1795735295000}`),a={name:`en/developer/diagnostics.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="diagnostics-and-safe-evidence" tabindex="-1">Diagnostics and safe evidence <a class="header-anchor" href="#diagnostics-and-safe-evidence" aria-label="Permalink to “Diagnostics and safe evidence”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Collect enough evidence to locate a failure without retaining account secrets or confusing diagnostics with recovery. Use a private test host and know which <a href="./transports.html">transport</a> is selected. The application installs one session collector; status components navigate to it rather than append entries while rendering.</p><h2 id="inspect-a-failure" tabindex="-1">Inspect a failure <a class="header-anchor" href="#inspect-a-failure" aria-label="Permalink to “Inspect a failure”">​</a></h2><ol><li>Open the contextual status action for the failing connection, plugin, sync pass or updater. Keyboard focus exposes the desktop log action as hover does.</li><li>Filter by source, severity and text, then inspect the selected entry&#39;s context and repetition count.</li><li>Copy selected or filtered entries when they explain the issue. Review exports before sharing them.</li><li>Compare native health with the frontend observation:</li></ol><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>A disconnected LIVE probe may be skipped. A compiled capability does not prove runtime availability. The UI panel is nonmodal on desktop; narrow layouts use <code>/debug</code> with a return location. Native text export uses <code>system.saveFile</code>; browsers download locally.</p><h2 id="understand-retention" tabindex="-1">Understand retention <a class="header-anchor" href="#understand-retention" aria-label="Permalink to “Understand retention”">​</a></h2><p><code>src/web/shared/diagnostics/log.ts</code> bounds history to 2,000 entries and 2 MiB of serialized UTF-8. Consecutive matching source/entity events within five seconds combine with a repetition count. Redaction happens before retention, including recognized credentials and URL secret locations; arbitrary unlabelled third-party secrets cannot always be recognized. Do not add raw settings, cookies, RPC parameters or HTTP bodies to collectors.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Expected result and status”">​</a></h2><p>The viewer provides bounded session history and context navigation, not a durable audit log. Reload/unmount clears memory. Clearing history does not clear a connection error or repair its cause. Cloud request IDs can help correlate a safe failure envelope; source coverage follows the installed collectors and does not guarantee capture of every registry or native error.</p><h2 id="verify-and-recover" tabindex="-1">Verify and recover <a class="header-anchor" href="#verify-and-recover" aria-label="Permalink to “Verify and recover”">​</a></h2><p>Run <code>bun scripts/task.ts test web diagnostics</code> and inspect the <a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/web/shared/diagnostics" target="_blank" rel="noreferrer">collector source</a>. Reproduce redaction, eviction and repeated-event behavior with synthetic values. For a conflict, unknown command or credential expiry, return to the owning recovery flow. Copying a diagnostic entry is evidence gathering; it never retries an action or approves a new trust policy.</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};